  echo "  seq       T-063 (sequential)"
  echo "  seq       T-064 (sequential)"
  echo "  seq       T-065 (sequential)"
  echo "  seq       T-066 (sequential)"
  echo
  echo "re-run one track:      --track <id>"
  echo "re-run a sequential:   --seq <T-xxx>"
  echo "only the gate:         --gate"
}

MODE="all"
TARGET=""
while [ $# -gt 0 ]; do
  case "$1" in
    --list) MODE="list" ;;
    --gate) MODE="gate" ;;
    --no-gate) WITH_GATE=0 ;;
    --track) MODE="track"; TARGET="${2:-}"; shift ;;
    --seq) MODE="seq"; TARGET="${2:-}"; shift ;;
    -h|--help) sed -n "2,14p" "$0"; exit 0 ;;
    *) red "unknown argument: $1"; sed -n "2,14p" "$0"; exit 2 ;;
  esac
  shift
done

if [ "$MODE" = "list" ]; then list_targets; exit 0; fi

prepare_env

case "$MODE" in
  all) run_all ;;
  gate) WITH_GATE=1; start_summaries; finish gate ;;
  track)
    case "$TARGET" in
      *) fail "unknown track: '$TARGET' — see the available ones with --list" ;;
    esac ;;
  seq)
    case "$TARGET" in
      T-060) event --type start --scope "seq:T-060"; start_summaries; run_seq_T_060 || true; finish "seq:T-060" ;;
      T-061) event --type start --scope "seq:T-061"; start_summaries; run_seq_T_061 || true; finish "seq:T-061" ;;
      T-062) event --type start --scope "seq:T-062"; start_summaries; run_seq_T_062 || true; finish "seq:T-062" ;;
      T-063) event --type start --scope "seq:T-063"; start_summaries; run_seq_T_063 || true; finish "seq:T-063" ;;
      T-064) event --type start --scope "seq:T-064"; start_summaries; run_seq_T_064 || true; finish "seq:T-064" ;;
      T-065) event --type start --scope "seq:T-065"; start_summaries; run_seq_T_065 || true; finish "seq:T-065" ;;
      T-066) event --type start --scope "seq:T-066"; start_summaries; run_seq_T_066 || true; finish "seq:T-066" ;;
      *) fail "unknown sequential task: '$TARGET' — see the available ones with --list" ;;
    esac ;;
esac
